const body = $json.body ?? $json;
const orderId = String(body.orderId || body.entityId || '').trim();
if (!orderId) { throw new Error('orderId is required'); }
const executionId = String(body.executionId || ('fraud-confirmed-' + Date.now()));
return [{ json: { ...body, orderId, executionId, workflowId: 'fraud-confirmed-response', workflowName: 'Xác nhận Gian lận & Chặn IP', receivedAt: new Date().toISOString() } }];

const base = $('🔍 Kiểm tra dữ liệu').first().json;
const order = $('🗄️ Tải đơn hàng').first().json || {};
const ip = order.ip_address || base.ip || 'không rõ';
const orderNumber = order.order_number || base.orderNumber || base.orderId;
const admin = base.adminEmail || 'admin@medicareguard.io';
const text = [
  '✅ <b>ADMIN XÁC NHẬN GIAN LẬN — MEDICAREGUARD</b>',
  '━━━━━━━━━━━━━━━━━━━━',
  '<b>Đơn hàng</b>  <code>' + String(orderNumber) + '</code>',
  '<b>IP khách</b>  <code>' + String(ip) + '</code>',
  '<b>Quốc gia</b>  ' + String(order.ip_country || base.country || 'không rõ'),
  '<b>Admin</b>  ' + String(admin),
  '<b>Lý do</b>  Admin confirmed fraud',
  '━━━━━━━━━━━━━━━━━━━━',
  'Hệ thống đã tự động chặn IP và cập nhật SOC.',
].join('\n');
const emailHtml = '<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; border: 1px solid #ddd; border-radius: 8px; overflow: hidden;">'
  + '<div style="background-color: #0f172a; color: #fff; padding: 20px; text-align: center;"><h2 style="margin: 0;">🚨 CẢNH BÁO GIAN LẬN - MEDICAREGUARD</h2></div>'
  + '<div style="padding: 20px; background-color: #f7fafc;">'
  + '<table style="width: 100%; border-collapse: collapse;">'
  + '<tr><td style="padding: 8px; border-bottom: 1px solid #eee;"><b>Mã đơn hàng:</b></td><td>' + String(orderNumber) + '</td></tr>'
  + '<tr><td style="padding: 8px; border-bottom: 1px solid #eee;"><b>IP khách hàng:</b></td><td>' + String(ip) + ' (' + String(order.ip_country || base.country || 'không rõ') + ')</td></tr>'
  + '<tr><td style="padding: 8px; border-bottom: 1px solid #eee;"><b>Admin xử lý:</b></td><td>' + String(admin) + '</td></tr>'
  + '<tr><td style="padding: 8px; border-bottom: 1px solid #eee;"><b>Lý do:</b></td><td>' + String(base.reason || 'Admin confirmed fraud') + '</td></tr>'
  + '</table>'
  + '<p style="margin-top: 20px; color: #e53e3e;"><b>✅ Hệ thống đã tự động chặn IP và cập nhật SOC.</b></p>'
  + '</div>'
  + '<div style="background-color: #edf2f7; padding: 10px; text-align: center; font-size: 12px; color: #718096;">Hệ thống MedicareGuard SOC tự động gửi.</div>'
  + '</div>';
return [{ json: { ...base, order, ip, orderNumber, order_id: orderNumber, admin, admin_email: admin, country: order.ip_country || base.country || 'không rõ', reason: 'Admin confirmed fraud', telegramText: text, emailHtml: emailHtml } }];
